<script>
document.getElementById('locate')?.addEventListener('click',()=>{const status=document.getElementById('location-status');if(!navigator.geolocation){status.textContent='Browser ini belum mendukung deteksi lokasi.';return}status.textContent='Meminta izin lokasi dari browser…';navigator.geolocation.getCurrentPosition(position=>{document.getElementById('latitude').value=position.coords.latitude.toFixed(7);document.getElementById('longitude').value=position.coords.longitude.toFixed(7);status.textContent='Lokasi berhasil diisi.'},()=>{status.textContent='Lokasi tidak tersedia. Periksa izin lokasi browser atau isi koordinat manual.'},{enableHighAccuracy:true,timeout:10000,maximumAge:60000})});
</script>
